import json,pathlib,hashlib
root=pathlib.Path('docs/ssw-workspace/kensetsu/exams/ten-by-forty')
exams={9:[],10:[]}
def add(e,s,refs,key,prompt,choices,explanation,wrong):
 n=len(exams[e])+1;sid=f'kensetsu-common-session-{s}'
 exams[e].append({'number':n,'promptJa':prompt,'choicesJa':choices,'correctIndex':0,'explanationJa':explanation,'objectiveKey':key,'claimJa':explanation,'sourceReferences':[{'sessionId':sid,'clusterId':f'{sid}-cluster-{c}','paragraphIds':[f'{sid}-cluster-{c}-p{p}' for p in ps]} for c,ps in refs],'distractorRationalesJa':[explanation]+wrong})
add(9,310,[(1,[1]),(3,[1,2])],'管の全長測定と対象ねじのゲージ検査は別である','切断した管の全長は図面どおりだった。継手もねじへ入る。この二つの結果について正しい説明はどれか。',['端面の向きと対象ねじのゲージ検査は、別の確認として残る。','全長が合うので、切断面の向きも合っている。','継手が入るので、ねじゲージの検査結果を記入できる。','ゲージを倉庫で保管していれば、今回の検査は実施済みである。'],'全長と端面形状は別項目であり、継手が入ることやゲージの所有は対象ねじのゲージ検査の代わりにならない。',['全長だけでは端面の向きや段差を判定できない。','継手のかみ合いは指定ゲージによる検査と異なる。','ゲージの存在と今回の検査の実施を混同している。'])
add(9,311,[(1,[1,2]),(3,[1,2]),(4,[1])],'切粉除去・脱脂・締付け・養生は互いの完了証拠にならない','ねじ部の切粉を取り除き、締付けの記録を作った。報告の表現として正しいものはどれか。',['切粉除去と締付けは記録したが、脱脂や養生・漏れの確認は別に残る。','切粉除去を記録したので、脱脂の記録も完了とする。','締付けたので、漏れ試験の結果も合格とする。','締付け終わりの時刻を、全材料共通の養生終了時刻とする。'],'切粉の除去は脱脂と異なり、締付けの完了も養生や漏れの確認を証明しない。',['固体の切粉除去は油の除去を証明しない。','締付けの記録を漏れ試験の結果へ置き換えている。','養生は材料と条件により異なり、締付け終了とも別である。'])
add(9,312,[(1,[1]),(2,[1]),(3,[1])],'溶接の熱源・被覆の保護・開先形状を識別する','配管溶接の用語の対応として適切なものはどれか。',['ガス溶接は燃焼熱、被覆アーク溶接はアーク熱を利用し、開先は接合端の形状を指す。','ガス溶接はアーク熱を利用し、開先は溶接棒の被覆を指す。','被覆は洗浄溶剤のことであり、開先は必ずV形になる。','被覆があれば酸化や欠陥は生じず、熱源の違いを読む必要もない。'],'熱源、被覆の保護機能、接合端の形状は異なる概念である。開先にはV形以外の形もある。',['ガス溶接の熱源と開先の意味を取り違えている。','被覆を溶剤と混同し、開先の形を一種類に限定している。','被覆は全欠陥を防ぐ保証ではなく、熱源の区分も必要である。'])
add(9,313,[(1,[1]),(2,[1]),(4,[1])],'機械的継手の保持と密封および接合結果は別機能である','ハウジング・ガスケット・ボルトを使う継手を説明する文で正しいものはどれか。',['管の保持と流体の密封は別の働きで、締付けの事実と圧力要求への適合も分ける。','管を保持できれば、ガスケットの状態を含め密封も確認できる。','カップリングという名称なら、管端加工と密封構造は製品間で共通である。','ボルトの締結記録が、接合結果の圧力試験記録を兼ねる。'],'メカニカル継手では保持と密封の役割を分け、組立て・締付けと接合性能の結果も分けて扱う。',['保持だけでは内側の密封部品の状態は分からない。','カップリングの名称は複数の構造で使われる。','締結の記録は圧力などへの適合結果ではない。'])
add(9,314,[(2,[1]),(3,[1]),(4,[1])],'塩ビ管の挿入目安と接着剤適合・養生を区別する','硬質塩ビ管に挿入位置の印がある。次の説明で適切なものはどれか。',['印は挿入量の照合の目安であり、接着剤の適合や使用前の養生を保証しない。','印があれば指定位置への挿入と接着は完了している。','塩ビ管用の接着剤なら、管種や温度を問わず同じ条件で使える。','挿入が済めば保持時間と使用前の養生も同時に終わる。'],'位置の印、実際の挿入、接着剤の条件、保持と養生はそれぞれ別に読む必要がある。',['印の存在は挿入の実施記録ではない。','接着剤は管種・寸法・温度などに対応させる。','保持と養生は異なる段階で、挿入完了から加圧可能とはいえない。'])
add(9,315,[(1,[1]),(2,[1]),(4,[1])],'ライニング鋼管は内側保護層と切断管端防食を別に評価する','ライニング鋼管を切断した。切断後の説明として正しいものはどれか。',['全長が合っても内側保護層の状態は別で、露出した管端の防食も別に確認する。','内側に保護層があるため、切断で露出した端面も自動的に保護される。','外面の被覆写真から、内側の材質と切断後の損傷を確定できる。','ねじが加工されていれば、全長と保護層の検査を兼ねられる。'],'ライニングは内側の保護層であり、切断による層の影響と露出管端の防食は別の確認対象である。',['既存の内側層だけでは露出端面の防食は証明できない。','内側層は外面写真だけでは同定・判定できない。','ねじの存在は長さや保護層の適合を証明しない。'])
add(9,316,[(1,[1]),(2,[1,2])],'冷媒銅管・排水管と外側保温材の役割を区別する','被覆銅管の断面寸法と用途を整理する。正しい記載はどれか。',['銅管を冷媒の経路、外側の保温材を熱移動に関わる層とし、排水経路とは分ける。','被覆の外径を銅管の接続外径として記載する。','冷媒管は室内機で生じた水を排出する経路として記載する。','銅管と保温材を同じ材質・同じ働きの一層として記載する。'],'冷媒は熱の受渡しに関わり、銅管はその流路、外側の保温材は熱移動に関わる。排水とは用途が異なり、外径も分ける。',['被覆を含む寸法は銅管そのものの外径ではない。','冷媒経路と室内機からの排水経路を混同している。','銅と保温材は材質も役割も異なる。'])
add(9,317,[(1,[1]),(3,[1]),(4,[1])],'被覆仕上げ・銅管端部と管内削り粉は別の状態である','保温材の切口は整い、銅管端部のバリ除去票も届いた。残る状態の説明はどれか。',['下の銅管の傷と管内の削り粉の残留は、これらの結果だけでは分からない。','外側が整っているため、下の銅管にも傷はない。','バリ除去票があるため、管内の削り粉も残っていない。','外側の縁が平らなら、内側の縁と内部清浄さをまとめて合格にできる。'],'被覆と銅管は別の対象であり、バリの除去と管内に粉が残らないことも異なる。',['被覆の仕上がりは下の金属面の無傷を証明しない。','バリを加工した記録だけでは削り粉残留は分からない。','外側の形状から内側や内部清浄さまで広げられない。'])
add(9,318,[(1,[1]),(2,[1]),(4,[1])],'管中心線の曲げと断面の真円修正は異なる加工である','管の経路は図面どおりに曲がっているが、断面の結果票はない。正しい理解はどれか。',['経路の適合と断面の扁平・しわなどの評価は別である。','曲げは真円修正と同じなので断面の結果票は不要である。','外径が同じ管は肉厚や質別が違っても加工性は同じである。','経路が合えば、断面の扁平がないことも確認できる。'],'曲げは経路、真円修正は断面に関わる。経路の結果だけで断面状態は分からず、工具適合にも肉厚や質別が関わる。',['経路と断面の変更を同じと誤認している。','銅管には肉厚・質別による加工性の違いがある。','経路寸法から断面の変形の有無は判定できない。'])
add(9,319,[(2,[1]),(3,[1])],'フレアナットの力伝達・接合面密封と形状測定は別である','フレア形状のゲージ票とナットの締結記録がある。これらから言えることはどれか。',['形状と締結の記録はあるが、接合の気密試験の結果を含むとはいえない。','ナットのねじがかみ合えば、それ自体が気密試験になる。','ゲージは形状と組立後の漏れを同時に検査する用具である。','ナットの外観が整えば、内部の密封面も確認済みになる。'],'ねじは力を接合面へ伝える側であり、密封面の働きと区別する。形状測定も組立後の気密試験とは目的が異なる。',['かみ合いの確認は気密の結果ではない。','形状の検査と接合性能の試験を混同している。','外側から内側の接合面の状態を確定できない。'])
add(9,320,[(1,[1]),(3,[1])],'ろう材を溶かす接合と難燃材の熱損傷を理解する','ろう接合と、その近くの難燃性保温材の説明で正しいものはどれか。',['ろう材を溶かして母材間に接合を形成するが、難燃性保温材も炎や伝熱による損傷を考える。','ろう接合は母材だけを溶かし、ろう材は保持用の部品である。','難燃性なら熱源の種類を問わず燃えず、損傷もしない。','ろう材と母材の役割は、熱く見える方を母材として識別する。'],'ろう接合ではろう材を溶かす。難燃性はすべての熱源に対する不燃・無損傷の保証ではない。',['溶ける材料とろう材の役割を取り違えている。','難燃性の意味を無条件の耐熱保証へ広げている。','熱いという外観だけで材料の役割は判定できない。'])
add(9,321,[(1,[1]),(2,[1]),(3,[1])],'保温材の形・材料群・外装機能を分類する','保温材の分類として正しい組合せはどれか。',['保温筒は形、ロックウールは繊維系材料、外装は表面保護などの機能に関わる。','保温筒は材質、ロックウールは発泡体、外装は内部厚さの測定機能に関わる。','保温帯は温度性能の等級で、グラスウールは金属外装の名称である。','外装が整えば、中の材料群と継目の状態を外観だけで識別できる。'],'形状名、材質名、層の役割を分ける。ロックウールは繊維系であり、外装の見た目は内部厚さや継目の証拠にならない。',['形と材質を取り違え、外装に測定機能を持たせている。','形状名と材質名を別の分類に置き換えている。','外装写真だけでは内部の材料・継目は分からない。'])
add(9,322,[(1,[1]),(2,[1]),(3,[1])],'保温保冷の熱移動低減と防湿・外装を区別する','天井内の冷たい配管について、保温保冷・防湿・外装を正しく説明したものはどれか。',['保温保冷は熱移動を減らし、防湿は水蒸気移動に関わり、金属外装だけで継目の防湿まで保証しない。','保温保冷は熱移動を完全になくすため、内部と周囲の条件は不要である。','金属外装があれば、継目を含む防湿と雨への性能はすべて成立する。','天井内は見えないので、防湿や保護の指定層は省略できる。'],'熱移動の低減、防湿、外装による保護は異なる観点である。隠ぺい部でも指定された保護・防湿条件は必要である。',['熱を減らす目的を完全遮断と誤認している。','外装の存在だけでは継目を含む層の性能を証明できない。','見えないことは必要な層を省く理由にならない。'])
add(9,323,[(1,[1]),(2,[1]),(3,[1]),(4,[1])],'GX継手の伸縮・屈曲・離脱抑制は異なる動きに対応する','GX形継手の機能の説明として適切なものはどれか。',['伸縮は相対的な長さ方向の移動、屈曲は方向変化、離脱抑制は抜ける方向の動きに関わる。','伸縮とは鋳鉄管本体がゴムのように伸びることである。','屈曲と伸縮は同じ動きなので、設計では一項目にまとめられる。','耐震の継手一つがあれば、管路全体はあらゆる変位に対応する。'],'GX形の各機能は異なる動きに対応し、管本体の伸びとは区別する。管路の耐震性は接合形式と全体の設計も合わせて考える。',['伸縮する部位を管本体と混同している。','方向変化と長さ方向の移動は異なる。','一つの継手の機能を無制限な全管路保証へ広げている。'])
add(9,324,[(1,[1]),(2,[1]),(3,[1])],'受口挿し口とゴム輪ロックリングの役割を対応させる','GX形の部品を整理する。正しい対応はどれか。',['受口は受ける側、挿し口は入る側で、ゴム輪は密封、ロックリングは離脱抑制に関わる。','受口は入る側、挿し口は受ける側で、両者の名称は逆に使う。','ロックリングがあれば、ゴム輪の材質や形式も適合済みである。','黒い輪の形が同じなら、管の呼び径を問わず同じゴム輪として扱える。'],'端部の方向と密封・離脱抑制の役割を分ける。ロックリングの存在は別部品であるゴム輪の適合を証明しない。',['端部名称の対応が逆である。','異なる役割の部品の適合を一方から推定している。','ゴム輪は形式・呼び径・材質などの対応が必要である。'])
add(9,325,[(1,[1]),(2,[1]),(3,[1]),(4,[1])],'据付けと接合前の清浄・指定滑剤・挿入実績を区別する','管を指定位置に並べ、型式票と標線の写真を受領した。接合の状況について最も適切なのはどれか。',['配置と識別の資料はあるが、接合面の状態や指定位置への挿入実績までは示していない。','管が並んでいるため、接合と挿入は完了している。','型式票が正しければ、接合面には砂や水分がない。','滑る油が倉庫にあれば、指定滑剤の確認も済んでいる。'],'据付けは配置の段階で、型式は清浄さを、標線の存在は挿入実施を証明しない。滑剤も対象部品への指定に対応させる。',['配置を接合完了へ広げている。','部材の識別と現物の面の状態は別である。','滑る性質だけで任意の油を指定滑剤の代わりにできない。'])
add(9,326,[(1,[1]),(2,[1]),(3,[1])],'GX接合の一点測定と全周確認・継手屈曲を区別する','GX形の接合で、一点の測定値と管路の曲がり図がある。正しい解釈はどれか。',['一点の値は全周の状態を示さず、継手での方向変化も管本体を曲げることとは異なる。','一点の値があれば、全周で同じ値だったと扱える。','管路図の曲がり角は、一つの継手が無条件に受け持つ角度である。','ゲージが写真に写っていれば、指定位置の測定は実施済みといえる。'],'確認した位置・範囲を限定して扱う。継手で許される方向変化は形式と条件に対応し、図面の角度をそのまま割り当てない。',['一点の結果を未測定範囲へ広げている。','設計上の曲がりと継手の許容条件を混同している。','用具の存在と検査実施は別である。'])
add(9,327,[(1,[1]),(2,[1]),(4,[1])],'EFの電熱線は樹脂接合の熱源であり補強材ではない','ポリエチレン管のEF接合の説明として正しいものはどれか。',['継手内の電熱線に通電して接合用の熱を生じさせる方式で、用途への適合は別に識別する。','電熱線は管の補強材であり、樹脂接合の熱とは関係しない。','PEという材質名が分かれば、EFかメカニカルかも決まる。','水道用とガス用はPEなら同じ施工条件なので、色の確認だけでよい。'],'EFは電気融着であり、電熱線は接合の熱を生む。材質や外観だけでは用途・接合方式の指定は確定しない。',['電熱線の熱源機能を補強機能と取り違えている。','樹脂管にも異なる接合方式がある。','同じ材質でも用途別製品があり、色は表示・規格の代わりではない。'])
add(9,328,[(1,[1]),(2,[1]),(3,[1]),(4,[1])],'EFスクレープ・清掃・位置保持の目的を区別する','EF接合の準備を、目的と正しく組み合わせたものはどれか。',['スクレープは指定範囲の表面加工、清掃は異物の状態、クランプは位置保持に関わる。','拭く清掃を行えば、スクレープも実施済みとして記録できる。','スクレープ範囲の印と挿入位置の印は、必ず同じ寸法を意味する。','通電できることが、管と継手の位置保持の成立を示す。'],'表面加工、清浄さ、挿入位置、位置保持は目的が異なる。準備後に汚れが付く場合もあり、時点も分ける。',['清掃と表面加工を同一工程としている。','加工範囲と挿入量は異なる目的の印である。','通電と位置を保つ条件は別である。'])
add(9,329,[(1,[1]),(2,[1]),(3,[1]),(4,[1])],'EF正常終了表示は融着面清浄さや冷却完了を証明しない','複数のEF接合のうち、一つの正常終了画面だけが届いた。正しい報告はどれか。',['その接合の機器表示を受領したが、面の清浄さ・冷却・他接合の結果は別である。','正常表示から全接合の清浄さと性能を合格にできる。','通電終了時刻が、そのまま冷却完了と次工程承認の時刻になる。','読めるバーコードなら、別型式継手のデータでも今回の指定を満たす。'],'表示の範囲は通電などの情報であり、面の状態や冷却、別接合への結果を含まない。継手現物とデータも一致させる。',['一接合の表示を全接合・全品質へ広げている。','通電終了と冷却条件の成立を混同している。','読取り可能性と現物へのデータ適合は異なる。'])
add(9,330,[(2,[1]),(4,[1,2])],'伸縮継手とケーブル余長は位置と収納条件を合わせて考える','建物との取合いに伸縮継手があり、ケーブル全長にも余りがある。接続位置を変更する際の理解として正しいものはどれか。',['継手の動きと、必要な位置で確保するケーブル余長・収納条件を合わせて考える。','伸縮継手があるため、ケーブルが張っていても余裕は十分である。','全長が余るため、どの接続位置にも必要な余長が確保される。','余った部分は、任意の小さな輪にして収納してよい。'],'管路の伸縮機能はケーブルの余裕を保証せず、全長の余りも必要な場所の余長とは限らない。収納条件も対応させる。',['管路の機能を内側ケーブルの余裕と同一視している。','余りが別の場所に集まる可能性がある。','余長の存在から任意の曲げ方・収納を認められない。'])
add(9,331,[(1,[1]),(2,[1]),(3,[1])],'光ケーブル外被・キンク・曲げ半径と張力の関係を理解する','光ケーブルに見える切断はないが、急な折れ曲がりが見つかった。正しい説明はどれか。',['断線が見えなくても伝送への影響があり、曲げ半径と張力も異なる条件として扱う。','外被に切断がなければ、光の伝送性能は確定する。','柔らかいケーブルなら、曲げ半径と張力の制限は同じになる。','キンクは外被だけの名称なので、内部の光の状態とは無関係である。'],'キンクなどの曲がりは光伝送にも関わる。外観と伝送結果、曲げ半径と張力はそれぞれ区別する。',['外観は内部伝送の結果ではない。','柔らかさは許容曲げ・張力の条件を共通にしない。','キンクを内部伝送と無関係としている点が誤りである。'])
add(9,332,[(1,[1,2]),(2,[1]),(4,[1])],'新設図の省略と一点試掘から既存設備全体を推定しない','通信更新図に水道は描かれず、試掘は一地点だけで行った。資料の読み方はどれか。',['図にない設備の存在も考え、資料上の位置と試掘で確認した地点・深さを分ける。','通信の工事図に水道がないので、地下に水道は存在しない。','一地点で管を見つけたため、先の区間も同じ位置と深さである。','古い台帳の位置は、変更の有無にかかわらず現地位置と一致する。'],'工事目的や新設図は既存設備の全範囲を示すとは限らない。台帳は現地との照合が必要で、試掘の結果も確認地点に限定する。',['図面への未記載を不存在の証拠にしている。','一点調査を全経路へ拡張している。','資料位置と現地位置は一致しない場合がある。'])
add(9,333,[(1,[1]),(2,[1]),(3,[1])],'探知無反応と地表印色だけでは埋設物を確定できない','探知機は無反応だったが、地表の線と色付き表示シートがある。正しい判断はどれか。',['機器方式・対象材質・現地条件を踏まえ、印の根拠やシートの文字情報も照合する。','無反応なので、線の下に埋設物はない。','シートの色だけで管理者と稼働状態を確定できる。','地表に線があるので、設備の種類と正確な深さまで確認済みである。'],'探知結果には方式や対象との関係があり、印には根拠記録が必要である。色や地表線だけでは設備の全情報は分からない。',['無反応は不存在の確定根拠ではない。','色だけでは管理者や使用状態は決まらない。','地表印を設備種類・深さの確認へ広げている。'])
add(9,334,[(1,[1]),(2,[1]),(3,[1])],'人力化や一点深さを区域拡張後の保護保証にしない','掘削を手工具へ変え、予定区域を広げた。以前の一地点の深さだけ分かる。正しい整理はどれか。',['人力でも損傷の可能性があり、追加区域や経路の曲がり・立上りを以前の一点調査と分ける。','手工具なら設備を損傷しないため、追加区域の調査も不要である。','工事名が同じなら、以前の協議結果は追加区域も含む。','最初に測った深さを追加区域の全経路へそのまま記入できる。'],'方法を人力に変えても無損傷の保証はなく、区域や形状の違いによって以前の調査をそのまま適用できない。',['手工具でも管やケーブルに力が加わり得る。','区域の拡張は工事名とは別の確認事項である。','深さは曲がり・立上りなどで変わる場合がある。'])
add(9,335,[(1,[1]),(2,[1,2])],'酸素濃度と硫化水素濃度は別の測定対象である','マンホールの確認表に酸素濃度だけが記載されている。これを「ガスは全部確認済み」とまとめない理由はどれか。',['酸素と硫化水素は別の対象で、一方の数値から他方の濃度は分からないため。','酸素と硫化水素は同じ濃度を示すので、二つ書くと重複するため。','内部が普通に見えるなら数値は不要で、外観を記入すべきため。','酸素濃度は設備外観の分類で、空気の測定には含まれないため。'],'測定値は何を測ったかと対応させる。酸素の結果だけで硫化水素その他の危険まで確認したとはいえない。',['異なる物質の濃度を同一としている。','外観だけでは空気の状態を判定できない。','酸素濃度の測定対象を取り違えている。'])
add(9,336,[(1,[1]),(2,[1,2]),(4,[1])],'マンホール作業の教育・監視・道路誘導は役割が異なる','マンホール脇に誘導員と囲いがあり、作業者の受講票もある。正しい説明はどれか。',['道路誘導・内部作業の監視・教育は別で、囲いや受講票だけで内部空気の確認は成立しない。','道路誘導員が近くにいれば、内部監視の担当も自動的に決まる。','受講票がある作業者は、全員が選任された作業主任者になる。','道路側の囲いは、内部の酸素や有害気体の確認記録を兼ねる。'],'各役割は対象が異なる。人や囲いの存在、受講の事実から監視体制や内部空気の確認まで推定しない。',['道路と内部で確認対象が異なるため自動兼任としない。','受講歴と作業主任者としての担当は別情報である。','囲いの機能は空気測定とは異なる。'])
add(9,337,[(1,[1]),(2,[1,2]),(4,[1])],'展開寸法と基準辺およびケガキ線の目的を識別する','板に複数のケガキ線がある。製作前の整理で正しいものはどれか。',['完成寸法と展開寸法を区別し、指定基準辺と各線の切断・曲げなどの目的を対応させる。','完成品の幅をそのまま平板寸法として使い、折る部分は考えない。','濃い線を正しい基準とし、薄い線は古いものと判断する。','ケガキ線はすべて切断の指示なので、目的の識別は不要である。'],'展開寸法は完成形と必ずしも同じではなく、ケガキは指定された基準と加工目的に結び付ける。',['曲げ条件により必要な平板寸法は変わる。','線の濃淡は指定基準の証拠ではない。','線には切断・曲げ・接続位置など異なる目的がある。'])
add(9,338,[(1,[1]),(2,[1]),(3,[1])],'板切断では工具能力・残す側・端部状態を別に捉える','金属板の切断準備と受渡しについて正しい組合せはどれか。',['工具を材質・厚さへ対応させ、切断線の残す側と加工後のバリを別に確認する。','金属が薄く見えれば、どの板金用はさみでも能力は足りる。','切断線が見えるので、残す側を伝えなくても二人の理解は一致する。','完成長さが合えば、端部の鋭い部分も指定どおりである。'],'工具の対応、線の両側の意味、切断後端部の状態は異なる情報であり、一つから他を確定しない。',['外観の薄さは材質・厚さに対する工具能力の判定ではない。','同じ線でも残す側の理解が異なる場合がある。','寸法とバリなどの端部状態は別項目である。'])
add(9,339,[(1,[3]),(2,[1]),(3,[1])],'曲げ方向・曲げ代・スプリングバックを区別する','板金曲げの説明で正しいものはどれか。',['線の位置と曲げる方向を分け、板厚等による曲げ代と力を除いた後の角度変化も考える。','線が正しい場所なら、表裏や曲げ方向が逆でも同じ完成形になる。','完成図の二辺の長さの和は、板厚を問わず必ず展開寸法になる。','加工中の角度と力を除いた完成角度は、必ず一致する。'],'位置・方向、展開に関わる曲げ代、力を除いた後のスプリングバックは別に読む。',['方向や表裏を取り違えると必要な形にならない。','曲げ代は板厚や形状等に関わるため単純和とは限らない。','スプリングバックにより角度が変わる場合がある。'])
add(9,340,[(1,[1]),(2,[1]),(3,[1])],'融接の母材溶融・仮固定・熱変形を区別する','板金の融接を説明したものとして正しいものはどれか。',['母材の接合部を溶融させる方式で、クランプ保持は仮付けと異なり、熱による寸法変化もあり得る。','融接は必ず棒だけを溶かし、母材を溶融させない方式である。','クランプが付いていれば、仮付けと本接合は済んでいる。','接合前の寸法が合えば、加熱後の寸法も変わらない。'],'融接の母材、保持と接合、加熱前後の寸法は分ける。溶加材を追加しない融接もあり、熱は変形に関わる。',['融接の定義をろう接合のように取り違えている。','保持の事実を接合の完了と混同している。','溶接熱による変形の可能性を除いている。'])
add(9,341,[(2,[1,3]),(3,[1])],'アングルフランジは枠接続と密封を別に評価する','交換ダクト用のアングルフランジが届いた。受入れ内容として正しいものはどれか。',['枠と本体の関係、既存側との端部対応、締結とパッキンの密封を分ける。','新しい側が指定どおりなら、既存端部の接合形式は問わない。','形鋼の枠が届いたことを、本体へ接続した結果として記録する。','ボルトが締まる外観を、気密試験の結果として記録する。'],'別枠を用いる構成、両側の端部適合、固定と密封の役割が関わる。片側や外観だけでは全接続の適合は分からない。',['接続は相手側との対応も必要である。','枠の存在と本体への取付け完了は異なる。','締結と気密の確認は異なる。'])
add(9,342,[(1,[1]),(2,[1]),(3,[1])],'共板とスライドオンの構成と角・辺の部品を識別する','共板フランジとスライドオンフランジの構成について適切なのはどれか。',['共板は本体の縁を成形する方式で、スライドオンは別枠を用い、角部品だけで辺の必要部品が揃うとは限らない。','共板もスライドオンも、必ず別に作った同一の枠を使う。','枠が本体へ入れば、固定と補強は完了している。','四隅の部品が揃えば、辺の接続用品の指定は不要になる。'],'本体の縁と別枠は材料構成が異なる。接続では角と辺の部品や固定・補強の指定も区別する。',['共板の本体縁成形という構成を取り違えている。','はまることと固定・補強の成立は別である。','角以外の接続用品が別途指定される場合がある。'])
add(9,343,[(1,[1]),(3,[1,2,3])],'丸ダクトの形状製法と差込み固定密封を識別する','丸ダクトの接合説明で正しいものはどれか。',['円形断面とスパイラルの製法名を区別し、差込みの重なり・ビスの固定・テープの密封も分ける。','スパイラルという名称だけで、すべて同じ接続方式とビス本数になる。','外側のテープの仕上がりは、内部の重なりと固定の実施を証明する。','ある口径の固定本数は、別口径でも同じ条件として使える。'],'形・製法・接続方式は同じ情報ではない。差込みの固定と密封を分け、固定用品の条件も寸法と仕様に対応させる。',['製法名から接続指定や本数を確定できない。','テープ外観から隠れた固定や重なりを確定できない。','口径と適用仕様の組合せを無視している。'])
add(9,344,[(2,[1]),(3,[1]),(4,[1])],'変圧・電路開閉と上流無電圧は異なる情報である','受電設備の機能を整理する文で正しいものはどれか。',['変圧器は電圧を変え、開閉機器とは役割が異なる。一部開放だけでは上流を含む無電圧は分からない。','変圧器は電圧変更と全電路の遮断を必ず一台で行う。','遮断器と断路器は、負荷電流や故障電流に対して常に同じ機能を持つ。','一方の開閉機器が開けば、上流も含め設備全体は無電圧である。'],'変圧、開閉機能、電路ごとの状態を分ける。遮断器と断路器の機能は同一とは限らず、一部の開放を全体へ広げない。',['変圧と全電路遮断を同一機能としている。','機器ごとの遮断機能の違いを無視している。','上流側の状態は一方の開放だけでは分からない。'])
add(9,345,[(1,[1]),(2,[1]),(3,[1])],'停電表示・別供給経路・残留電荷の状態を区別する','主電源を止めた記録と消灯の写真が届いた。判断として適切なのはどれか。',['別供給や周囲の活線、蓄えられた電荷の状態まで確認した記録とはいえない。','消灯は全電源と機器内電荷がなくなった証拠である。','主電源の停止時刻だけで、全回路の無電圧状態が分かる。','残留電荷は供給中だけに生じ、供給停止後は確認対象にならない。'],'表示や主電源の記録は別経路や残留電荷の確認と異なる。停止後も機器に電気が蓄えられる場合がある。',['照明と全回路・電荷を同一視している。','一供給源の記録を全経路へ拡張している。','残留電荷は供給停止後の蓄えられた電気にも関わる。'])
add(9,346,[(1,[1]),(2,[1]),(4,[1])],'短絡の回路範囲と意図的接地・保護動作を理解する','電気故障の説明で適切なものはどれか。',['短絡は単相や直流にも関わり、意図した保護接地は地絡と区別し、遮断動作だけで原因解消としない。','短絡は三相の線同士だけで起き、直流には関わらない。','大地へつながる線があれば、意図した接地でも地絡である。','保護機器が遮断すれば、故障原因も解消されたことになる。'],'回路方式、意図された接続、故障への保護動作は別の観点であり、用語と観測の範囲を保つ。',['短絡の対象を三相だけに限定している。','保護接地と意図しない故障経路を混同している。','保護動作は原因が直った証拠ではない。'])
add(9,347,[(1,[1]),(2,[1]),(3,[1]),(4,[1])],'圧着の材料適合・ダイス・保持と電気性能を区別する','端子に電線が入り、圧着後も外れない。正しい解釈はどれか。',['材質・構造・サイズとダイスの対応、さらに電気的性能は別に評価する。','穴へ入ることが線の材質と構造の適合を証明する。','工具本体が同じなら、端子を替えてもダイスは必ず同じでよい。','外れないことが電気的性能を示すので、端子や周囲の条件は不要である。'],'物理的に入ること、正しい加工の組合せ、保持、抵抗・発熱などの電気的確認は異なる。許容電流にも端子や周囲が関わる。',['寸法上の挿入と材料適合は別である。','本体が同じでもダイスの指定は異なる場合がある。','保持だけでは電気性能は分からず、条件も無視できない。'])
add(9,322,[(4,[1,2])],'保温材の収縮は材料温度と条件に依存し現在の隙間と将来状態は別である','保温材の継目は今ぴったり合っている。温度変化後の状態について正しい考え方はどれか。',['現在の隙間の有無と変化後の状態を分け、収縮を材質・温度・試験条件へ対応させる。','今隙間がないため、温度が変わっても隙間は生じない。','ある製品の収縮率は、すべての保温材へ共通に使える。','継目の写真一枚が、温度変化後の計算結果を兼ねる。'],'保温材の収縮は材質や温度、試験条件に関わるため、現在の写真から変化後の状態や他製品の値を確定しない。',['現在の状態を将来の条件へ無条件に広げている。','収縮率を異なる製品へ一律に適用している。','写真は熱条件との対応や計算を示すものではない。'])
add(9,335,[(3,[1,2]),(4,[1])],'朝の空気測定と換気設備存在は午後の入場条件を保証しない','朝に空気を測定した後、流入条件が変わった。送風設備は置かれている。午後の説明で適切なのはどれか。',['朝の値を現在の全場所へ広げず、時刻・場所・条件変化と必要な管理を対応させる。','朝の値があるので、午後も全場所の空気は同じである。','送風設備があるため、現在必要な空気の条件も成立したといえる。','換気できない場合でも、普通のマスクの有無で入場条件を置き換えられる。'],'空気は流入や換気・作業により変わる場合がある。過去の測定や設備の存在だけで現在の入場条件は確定せず、通常のマスクで換気を代用しない。',['測定の時点と範囲を無視している。','設備の存在と必要状態の維持を混同している。','普通のマスクは換気不能時の代替条件ではない。'])
add(10,348,[(1,[1]),(2,[1]),(3,[1]),(4,[1])],'架空線に対しては機械の可動範囲と接近条件を評価する','荷台を上げる車両と架空線の関係で正しいものはどれか。',['走行時の高さと作業時の可動範囲を分け、線の区分と離隔条件を対応させる。','細い架空線なら通信線と判断し、機械の高さ確認から除く。','車体が通れた実績は、荷台を上げる作業時にも適用できる。','線にカバーがあれば、機械が触れることも許可されている。'],'線の外観だけでは用途は決まらず、機械の動きで占める範囲も変わる。接触していないことやカバーの存在だけで適合を判断しない。',['太さだけでは通信・電力や危険の区分を同定できない。','停止・走行時と荷台上昇時では範囲が異なる。','カバーは接触の許可を意味しない。'])
add(10,349,[(1,[1]),(2,[1]),(3,[1]),(4,[1])],'道路使用占用の制度・許可範囲と通行者保護を区別する','道路工事の許可証と車両用配置図が届いた。適切な整理はどれか。',['使用・占用の制度と許可時間等を識別し、歩行者経路と現場の保安状態は別に捉える。','許可証一枚で使用と占用の全手続きが完了したといえる。','同じ工事名なら、作業時間を変えても許可の範囲内である。','車両が通れる図なので、歩行者の経路も確保されたといえる。'],'許可制度・対象条件と実際の保安状態は別であり、車両と歩行者の条件も同一ではない。',['制度の目的と確認する側は異なるため一枚から全完了としない。','時間や場所・行為も許可条件である。','車両用経路の確認は歩行者経路の確認ではない。'])
add(10,350,[(1,[1]),(2,[1]),(3,[1]),(4,[1])],'道路覆工・柵・材料保管と注意灯は異なる保護対象を持つ','夜間道路工事で、穴には板、周りには柵、道路端には材料があり、注意灯も点いている。正しい説明はどれか。',['板の耐荷重、柵の区分、材料の移動対策、見え方や周辺影響は異なる確認対象である。','板が見えるので車両荷重への対応は成立している。','材料を道路端へ寄せたため、風による飛散対策も完了した。','注意灯が点けば、開口部の管理と周辺騒音の確認は終わる。'],'覆う・区切る・保管する・見せる機能を分ける。用品の存在や位置だけでは必要な保護条件の成立は分からない。',['板の存在は耐荷重の確認結果ではない。','位置と固定・飛散対策は別である。','灯りは開口部の全管理や騒音の確認を兼ねない。'])
add(10,351,[(1,[1]),(2,[1]),(3,[1])],'アクセス設備の敷設完了と利用開始・環境別条件を区別する','架空の通信経路を地下へ移し、建物までケーブルを敷設した。正しい説明はどれか。',['通信用途が同じでも支持や管路等の条件は変わり、敷設だけで接続・利用開始まで済んだとはいえない。','用途が通信なら、架空と地下で同じ支持構造を使う。','屋外用ケーブルの名称は、屋内の全用途への適合を意味する。','建物へケーブルが届いた時点で、利用者は通信サービスを使える。'],'経路と環境の条件は用途名だけでは決まらず、ケーブル敷設と接続・サービス利用の確認も区別する。',['架空と地下では支持や周囲の条件が異なる。','屋外用の名称から屋内全用途への適合は決まらない。','到達だけでは接続や必要な確認の完了は分からない。'])
add(10,352,[(1,[1]),(2,[1]),(3,[1])],'光とメタルの伝送信号・外被・引込み先を識別する','通信ケーブルの正しい説明はどれか。',['光は光信号、メタルは電気信号の伝送に関わり、外径や到着先だけでは内部構成や正しい利用者への接続は確定しない。','黒い外被なら、光とメタルのどちらでも同じ信号を伝える。','外径が合えば、内側の線の種類と本数も必ず同じである。','引込み線が建物に届けば、指定された利用者への接続は確認済みである。'],'伝送方式、外側の保護、内部構成、利用先の識別は別の情報として扱う。',['色は伝送方式の代わりにならない。','外径だけでは内部構成は決まらない。','建物への到達と正しい利用先への接続は異なる。'])
add(10,353,[(1,[1]),(3,[1]),(4,[1])],'クロージャの保護・電柱支持と地上高を理解する','クロージャと電柱について正しいものはどれか。',['クロージャは接続や分岐を収容・保護し、電柱は架空設備を支持するが、色や空き具合だけで用途や追加可否は決まらない。','灰色のクロージャは全製品で光用と決まる。','電柱が空いて見えれば、任意の設備を追加できる。','別の場所の地上高は、どの道路横断部にも同じ条件として使える。'],'保護用品と支持構造の役割を分け、製品の用途、支持条件、場所ごとの地上高の指定を対応させる。',['色分けの例は全製品共通の用途規則ではない。','支持条件と管理者との確認が必要で、見た目は承認ではない。','地上高は設備・道路・交差などの条件による。'])
add(10,354,[(1,[1]),(2,[1]),(3,[1]),(4,[1])],'通信管路・ハンドホール・とう道共同溝の構造を区別する','通信土木設備の説明として正しいものはどれか。',['管路はケーブルを収容し、とう道は大容量のトンネル形式で、共同溝では複数設備との関係も読む。','一端の管口が見えれば、全経路の通過は確認できる。','ハンドホールは小さいマンホールなので、人が入る条件も同じである。','C・C・BOXは、すべて同じU字形の単品だけを意味する。'],'設備名と実際の構造を区別する。管口の一部確認や名称だけで全経路・入場条件・施設全体を確定しない。',['管口の確認を全経路へ広げている。','人が入るかなどの設計が異なり、名称は入場条件ではない。','管路部や特殊部などの構成を単一部品へ限定している。'])
add(10,355,[(1,[1]),(2,[1]),(3,[1])],'土被りの基準位置と縦断勾配を理解する','管路の高さ資料を整理する際に正しいものはどれか。',['土被りは管頂等までの距離で、縦断で高さ変化を読み、両端の落差だけで中間排水を確定しない。','管中心までの深さは、そのまま土被りとして記入できる。','平面図の位置が分かれば、各地点の管頂高さも分かる。','両端に高低差があれば、中間で水が停滞する部分はない。'],'管頂・中心・底という測定位置を区別し、経路の高さと中間状態は別に把握する。',['測定の終点が異なる。','平面位置は高さの情報を兼ねない。','全体落差だけでは局所的な勾配は分からない。'])
add(10,356,[(2,[1]),(3,[1]),(4,[1])],'平行水平間隔と交差垂直間隔・了解範囲を区別する','平行区間の水平間隔票と管理者の同区間の了解がある。交差部へ引き継ぐ説明はどれか。',['測定基準を保ちつつ、交差部の垂直間隔とその場所の了解は別として残す。','水平間隔の数字を、そのまま交差部の垂直間隔欄へ移す。','同じ数字なら、中心間と外面間のどちらの測定でも同じ位置関係である。','一つの平行区間の了解は、別の交差部の承認も意味する。'],'方向や測る端、場所ごとの確認を分ける。平行区間の測定・了解を交差部へ自動拡張しない。',['水平と垂直は異なる位置関係である。','測定基準が違えば数字が同じでも関係は異なる。','了解が対応する場所の範囲を超えている。'])
add(10,357,[(1,[1]),(2,[1]),(4,[1])],'マンドレル通過と気密は目的が異なり結果範囲は孔に対応する','一つの孔でマンドレルが通った。試験について正しい説明はどれか。',['その孔の通過性に関わる結果であり、気密や全孔の承認とは区別する。','通過したため、その孔の空気漏れも確認済みである。','一つの孔を試験すれば、同系統の全孔を合格とできる。','気密試験は用具が管内を通るかを確かめる試験である。'],'通過試験は所定用具が通るか、気密試験は空気漏れなどを確認する。実施対象・条件と判定範囲を対応させる。',['通過性と漏れの性能は別である。','一孔の結果を未試験の孔へ広げている。','気密と通過の目的を入れ替えている。'])
add(10,358,[(2,[1]),(3,[1]),(4,[1])],'耐火性・断熱性と炉層別材料数量を区別する','炉材の必要総数は届いたが、耐火用と断熱用の内訳が分からない。正しい理解はどれか。',['耐火性と断熱性は別の評価なので、総数だけでは各層の指定材料が揃ったといえない。','軽いれんがは、すべての高温面で耐火れんがの代わりになる。','耐火表示があれば、断熱性もすべて同じである。','総数が一致すれば、層別の材質や配置の確認は不要である。'],'熱に耐える働きと熱移動を抑える働きを分け、図面の部位・層ごとの材料へ内訳を対応させる。',['軽さだけでは使用位置への適合は決まらない。','耐火と断熱は同じ評価ではない。','数の一致と部位・種類の一致を混同している。'])
add(10,359,[(1,[1]),(2,[1]),(3,[1]),(4,[1])],'耐火モルタルの熱硬性気硬性と供給形態を識別する','耐火モルタルの説明で正しいものはどれか。',['熱硬性は加熱による結合、気硬性には常温乾燥等で強度が生じる製品があり、供給形態にも別の条件がある。','気硬性という表示は、塗布後すぐ使用できることを意味する。','耐火用と一般建築用はモルタルという名前が同じなので交換できる。','湿った製品から粉状へ替えても、同じ配合と調整方法が適用される。'],'分類名は具体的な使用開始時期や全養生方法を決めるものではない。製品・れんが・炉条件と供給形態を対応させる。',['常温は待ち時間不要の意味ではない。','用途や結合する材料の指定が異なる。','供給形態の違いを無視している。'])
add(10,360,[(2,[1]),(3,[1,2])],'目地寸法材料と切片の設計対応を評価する','炉の角を補修する案で、目地は均等に見え、別の炉で使った切片を使いたいという。適切な説明はどれか。',['目地は寸法と材料を分けて捉え、切片も今回の部位の設計に対応させる。','目地が均等に見えれば、指定寸法と材料は確認済みになる。','別の炉で使えた切片寸法なら、今回の角でも適合する。','小さい切片は、全炉で同一の分数だけを基準に扱える。'],'目地の外観だけでは指定値・材料の適合は分からず、積み方や切片は形状・部位の設計に対応させる。',['外観は寸法記録や材料確認の代わりではない。','過去の別部位の実績は今回の適合理由ではない。','教材は一律の分数規則へ一般化しない。'])
add(10,361,[(1,[1]),(2,[1]),(3,[1])],'消火ポンプの低頻度利用・水源と呼水機能を理解する','消火ポンプを長く使っておらず、水槽には水がある。正しい説明はどれか。',['低い使用頻度は点検不要を意味せず、水源からの経路と方式に応じた呼水も別の条件である。','出動がなかったため、機能は正常と判断できる。','満水表示があれば、ポンプへ必要な水が届く条件はすべて成立する。','呼水槽の構成は、すべての方式の消火ポンプで同じである。'],'点検と使用実績は別であり、水量だけでは吸込み経路の成立は分からない。呼水はポンプや経路を満たす機能で方式に対応する。',['使わなかったことは機能の証拠ではない。','貯水と必要な水の供給は同一ではない。','呼水設備は方式によって異なる。'])
add(10,362,[(1,[1]),(2,[1]),(3,[1]),(4,[1])],'締切運転の水温対策と空運転対応を区別する','締切運転と逃し機能の説明で正しいものはどれか。',['締切運転は吐出量がない運転で、逃し等の水温上昇対策は水がない状態への対応とは別である。','締切運転は水がない状態だけを指す。','逃し機能があれば、水なしでも運転できる。','外付け逃し配管が見えない製品は、必ず水温対策が欠品している。'],'吐出量のない運転と空運転を混同しない。水温対策には外付け配管や本体機構などがあり、方式と機能を区別する。',['吐出量の有無と水の有無を入れ替えている。','温度対策を空運転保護へ広げている。','製品ごとの機構の違いを無視している。'])
add(10,363,[(1,[1]),(2,[1]),(3,[1]),(4,[1])],'ポンプ回転・揚程流量と表示単位を区別する','ポンプの動画は回転を示し、別品番の盤の数値が単位なしで転記されている。適切な読み方はどれか。',['回転と送水性能を分け、表示が流量か電流か、単位や測定条件を確認して評価する。','回転が見えるので、定格の送水量に達している。','前の盤と同じ位置の数字なら、今回も流量である。','圧力値一つで揚程と流量を含む全性能を判定できる。'],'作動、表示項目、単位、送水性能は異なる情報であり、数値を対象条件に対応させる。',['電動機の回転だけでは定格送水性能は分からない。','盤の表示項目は製品ごとに異なる場合がある。','圧力一値は全性能の結果ではない。'])
add(10,364,[(1,[1]),(2,[1]),(3,[1]),(4,[1])],'認定ポンプと現場消火配管・代替管材料は別の適合対象である','認定消火ポンプに、同径の別ライニング管を提案する。正しい説明はどれか。',['ポンプ認定と現場配管の適合は別で、ライニングの熱による挙動や対象仕様との対応も考える。','ポンプの証票があるので、全現場配管材も承認済みである。','内面の色が似ていれば、材質と耐熱性も同じである。','同じ径で接続できる代替管なら、消火用の材料確認は不要である。'],'認定範囲と配管の材料条件を区別する。内面の色や接続寸法は、材質・熱挙動・使用条件への適合を証明しない。',['ユニットの認定を工事材料全体へ拡張している。','外観色を材料証明としている。','同寸法でも材料条件は変わる。'])
add(10,365,[(1,[1]),(2,[1]),(3,[1])],'死亡件数と発生率・事故型と原因は別である','過去の死亡災害表で、職種Aの件数がBより多い。人数の資料はない。正しい読み方はどれか。',['対象期間・範囲を示し、件数差だけでは一人当たりの危険を決めず、同じ事故型でも原因は分ける。','Aの一人当たりの危険は、人数資料がなくてもBより高いと決まる。','過去の死亡件数は、今年の現場の全けが件数として使える。','同じ事故型に分類された災害は、原因も同じである。'],'件数は分母のある発生率とは異なり、死亡災害と全けが、事故型と原因も区別する。',['一人当たり比較の分母がない。','時点・範囲・死亡と全けがの違いを無視している。','同じ型に異なる原因が関わる場合がある。'])
add(10,366,[(1,[1]),(2,[1]),(4,[1])],'地上穴への墜落と転倒後落下・物の崩壊を区別する','地上通路のホースの横に穴があり、別の場所では積み材が崩れた。正しい理解はどれか。',['転倒から穴への落下が続く可能性を考え、積み材の崩れは単独工具の落下と仕組みを分ける。','地上通路なので、墜落の対象はない。','転倒に分類すれば、その後に穴へ落ちる危険は対象外になる。','積み材の崩れと工具落下は物の事故なので、発生の仕組みも同じである。'],'地上の穴も墜落に関わり、複数事象が続くことがある。物の種類だけでなく落下・崩壊の起き方を読む。',['建物上以外の穴も対象になる。','分類一つでは周囲の危険は消えない。','崩れる機構と単独物の落下は異なる。'])
add(10,367,[(1,[1]),(2,[1]),(3,[1]),(4,[1])],'高所作業床・墜落制止器具着用・教育と使用条件を区別する','作業床とハーネス着用写真、受講修了証がある。正しい説明はどれか。',['床・姿勢、取付設備とランヤードの組合せ、今回の器具選定はそれぞれ確認対象である。','床があれば、周囲へ身を乗り出す作業の条件も満たす。','着用写真だけで、取付けも適切に行われたといえる。','修了証があれば、別品番でも以前の付け替え方法を共通に使える。'],'床の存在、着用、教育はそれぞれの事実であり、姿勢・取付け・製品と作業への適合を証明しない。',['床と手すりの役割、姿勢条件を区別していない。','着用と取付けの結果は別である。','製品ごとの指定と現場条件は修了証から決まらない。'])
add(10,368,[(1,[1]),(2,[1]),(3,[1]),(4,[1])],'工事区画と移動・架空接触・旋回後退の危険を分ける','道路沿いの工事で柵を移し、機械の作業範囲も変えた。適切な計画はどれか。',['新通路と旋回・後退時の人の位置を見直し、道路車両と架空設備の関係や場外移動も分けて考える。','誘導員の人数が同じなら、旋回と後退の範囲も以前どおりでよい。','作業者が車道から離れていれば、車両と架空線の接触の影響はない。','現場内の点検票があれば、帰りの道路運搬の確認も済む。'],'区画・動き・人の経路と移動条件を対応させる。人員の存在や区域内の確認だけでは別の危険は管理されない。',['異なる機械動作と人の位置の確認を人数で代用している。','架空線への車両接触が高所作業者へ影響する場合もある。','現場内と道路移動は別の確認である。'])
add(10,369,[(1,[1]),(2,[1]),(3,[1])],'吊り荷区域・積み材支持と帯電防止の保護範囲を理解する','吊り荷・積み材・電気用品について正しい説明はどれか。',['短時間でも荷の下の通行を許す理由にはならず、立つ積み材の安定と帯電防止用品の感電保護も別に考える。','一瞬の通行なら、吊り荷の下も落下から保護される。','写真に倒れた柱がなければ、必要な支持は成立している。','帯電防止の手袋なら、感電から守る絶縁用品と同じ性能である。'],'時間の短さ、立った外観、似た保護表示を必要な保護条件へ置き換えない。',['短時間は落下の保護ではない。','外観だけでは支持・固定の適合は分からない。','帯電抑制と感電用の絶縁保護は異なる。'])
add(10,370,[(1,[1]),(2,[1]),(3,[1]),(4,[1])],'酸欠中毒と救助二次災害・装備所有を区別する','マンホール内で人が倒れたとの連絡がある。救助に関する理解で正しいものはどれか。',['酸欠と硫化水素中毒は別の危険であり、救助者も被災し得るため、所定の緊急連絡と専門対応へつなげる。','開いた蓋からにおいがしなければ、誰でも救助に入れる。','酸素の記録が一つあれば、硫化水素を含む空気全体は確認済みである。','呼吸用装備が置かれていれば、教育や計画を問わず入れる。'],'二次災害は助けに入る人にも広がる。外観・一測定・装備の存在を入場条件の代わりにせず、定められた体制へつなぐ。',['見た目やにおいでは空気の安全を判断できない。','異なる測定対象を一つにまとめている。','装備所有と実施条件は別である。'])
add(10,371,[(1,[1]),(2,[1]),(3,[1]),(4,[1])],'掘削土留め・周囲通路・機械据付けと混在調整を区別する','溝の近くへ大型機械が届き、同時間に溝内配管を予定している。正しい整理はどれか。',['土と荷重・土留め、周囲歩行経路、機械の固定、作業時間と場所の干渉を分けて調整する。','浅く見えるため、土や周囲荷重を問わず溝内へ入れる。','機械の到着票があれば、据付けと使用準備は終わっている。','両作業の単独票があるので、互いの影響も解消済みである。'],'深さや到着・単独計画だけでは崩れ、転落、設置安定、複合作業の条件は確定しない。',['深さ一項目は崩壊しない保証ではない。','運搬と据付けの安定は別である。','単独計画は相互干渉の調整結果ではない。'])
add(10,372,[(1,[1]),(2,[1]),(3,[1]),(4,[1])],'朝礼全体情報を当日班作業と具体的危険予知へ対応させる','朝礼で搬入変更を聞き、班では昨日と違う機械を使う。適切な話合いはどれか。',['班の通路への影響と新しい機械の条件を具体化し、当日の点検と対策へ結び付ける。','朝礼へ参加したので、班の個別段取りはすべて確認済みとする。','昨日のミーティングを同じ言葉で読めば、今日の変更も確認できる。','危険という名前を言えば、具体的対策と点検も実施したことになる。'],'全体連絡を自分の作業条件に対応させ、危険名だけでなく具体的対策と当日の機械状態も考える。',['参加と個別作業の全確認は異なる。','同じ文言の反復では変更は分からない。','命名は対策確認や点検の実施とは違う。'])
add(10,373,[(1,[1]),(3,[1]),(4,[1])],'安全施工サイクルは日中変化と工程調整・終業残置状態を含む','昼の搬入が増え、翌朝は二班が同じ入口を使う。終業時には開口が残る。正しい扱いはどれか。',['昼の通路を見直し、翌朝の場所・時間を調整し、残る開口等の管理を引き継ぐ。','朝に確認したので、昼以降の変更は明日の対象にする。','二班が各自予定を出せば、入口利用の共通合意は成立する。','終業時刻を書けば、人が帰った後の開口管理は完了する。'],'安全施工サイクルは開始前から終業までつながり、変化・相互工程・残置状態を別に扱う。',['朝の一回で一日の全状態は分からない。','個別提出は場所と時間の共通調整ではない。','人の退場や時刻の記録は残る危険の管理を証明しない。'])
add(10,374,[(1,[1]),(2,[1]),(3,[1]),(4,[1])],'雇入れ作業変更教育は経験や受講時間ではなく必要内容に対応する','経験者が新しい材料と工具を扱う。受講票には時間だけがある。適切な評価はどれか。',['今回の危険性・有害性、点検・保護具や異常時対応等の必要内容を受講内容と照合する。','長い建設経験があれば、変更後の全内容を教育済みとする。','工具操作の説明は、点検・健康予防・退避まで含む全教育の証拠となる。','受講時間が長ければ、対象業務の内容と理解は確認できる。'],'経験、操作説明、受講時間と、今回必要な安全衛生教育の内容は別である。けがと健康への影響も区別する。',['職種や工程変更で新たな教育範囲があり得る。','操作説明だけで他の必要内容を満たすとは限らない。','長さだけでは内容への適合は分からない。'])
add(10,375,[(1,[1]),(2,[1]),(3,[1]),(4,[1])],'新規入場教育は現場条件と連絡方法・理解に対応する','別現場の入場証を持つ作業者へ、新しい現場を説明する。適切な内容はどれか。',['今回の混在作業や区域、指揮命令と連絡方法・避難経路を伝え、理解も確かめる。','前の入場証があるので、今回の現場説明は完了済みとする。','責任者の氏名を伝えれば、連絡の方法と場所も理解したといえる。','資料を渡した枚数が、受け手の理解度を示す。'],'現場固有の条件を伝える教育は別現場の証票と異なり、伝達の事実と理解も分ける。',['別現場の受講では今回の条件は分からない。','氏名だけでは実際に連絡できるとは限らない。','配布量は理解した証拠ではない。'])
add(10,376,[(1,[1]),(2,[1]),(3,[1]),(4,[1])],'保護装備の規格表示と現在損傷・使用条件は別である','長期間保管した装備には適合表示と購入年が残る。正しい判断はどれか。',['頭・足・墜落等の保護目的を分け、現物状態と今回の取付け・落下空間等へ対応させる。','適合表示があれば、今の損傷状態を別に確認しなくてよい。','同じ高さの場所なら、取付け先や落下空間が違っても使用条件は同じである。','購入年だけを古い規格の説明へ当てはめれば、現在の使用適合は決まる。'],'保護対象、規格、現物状態、作業ごとの使用条件は異なる情報であり、購入時の記録だけで現在を判定しない。',['規格への適合と現在損傷の確認は別である。','高さ一項目では全使用条件は決まらない。','移行期の説明や購入年だけでは現物の適用条件を確認できない。'])
add(10,377,[(2,[1]),(3,[1]),(4,[1])],'眼呼吸手顔の保護具は対象機能に応じて選ぶ','保護具の機能に関する説明で正しいものはどれか。',['粉じんのろ過と酸素供給、透明な顔面保護と溶接遮光は別で、手袋も回転機械の巻込み条件を考える。','防じんマスクがあれば、酸素欠乏の場所にも対応できる。','透明な顔面シールドが広ければ、溶接に必要な遮光を証明する。','材料運搬用の手袋は、どの回転加工でも同じ条件で使う。'],'保護対象ごとに機能が異なり、形や所有だけでは別用途への適合は分からない。',['ろ過する用品が酸素を供給するとは限らない。','顔を覆う面と遮光性能は異なる。','機械と作業によって巻込み等の条件が変わる。'])
add(10,378,[(1,[1]),(2,[1]),(3,[1]),(4,[1])],'暑さ指数・休憩運用と体調異変報告を区別する','屋内の熱い設備の近くに冷房休憩所ができた。適切な理解はどれか。',['現場の熱・湿度等を含む評価と利用時間の計画を考え、本人の我慢だけで異変時の継続を決めない。','外の予報気温は、そのまま屋内設備付近の暑さ指数である。','休憩所の設置写真があれば、全員の体調と対策運用は確認済みである。','緑十字の印を見つければ、救急箱の内容物と緊急連絡先も分かる。'],'熱中症の危険は気温だけでなく環境や作業条件に関わる。設備、体調、連絡情報は別に捉える。',['気温と湿度・熱等を含む指数を混同している。','設備の存在は利用計画や個人状態の証拠ではない。','印は具体的な内容物・連絡先を表す情報ではない。'])
add(10,379,[(1,[1]),(2,[1]),(3,[1]),(4,[1])],'ヒューマンエラーは背景環境と品質工程への影響も考える','似たスイッチの取違えが続くが、けがはなかった。原因調査として適切なのはどれか。',['表示・配置などの背景と品質・工程への影響も調べ、教育だけでなく識別の仕組みも考える。','けががないため、原因調査と品質確認は不要である。','注意不足という分類が付けば、設備の背景条件は除外できる。','受講回数が増えれば、表示の識別問題はすべて改善されたといえる。'],'行動だけに原因を限定せず、環境と仕組み、品質や工程の影響を捉える。分類や教育実施は改善結果そのものではない。',['誤りは納入違いや手直しなどにも影響する。','分類は背景の調査を終える根拠ではない。','教育と設備改善は異なる対策で、回数は結果の証拠ではない。'])
add(10,380,[(1,[1]),(2,[1]),(3,[1]),(4,[1])],'思い込み・部分一致・集中時の注意範囲を理解する','毎回同じ搬入順で、品番の末尾も似ている。近くでは細かな取付け作業がある。適切な認識はどれか。',['予想と実際の合図を分け、品番全体を識別し、集中で周囲への注意が狭まる条件も考える。','慣れた順番は、聞いていない次の指示の代わりになる。','末尾の番号が同じなら、品番全体も同じと扱える。','取付けに集中すれば周囲の動きも必ず把握でき、背後確認は不要となる。'],'思い込みや一部一致は誤認に関わる。集中時の周囲・足元・背後など見ていない範囲も考える。',['予想は実際の指示ではない。','部分一致から全部一致は導けない。','集中は周囲への注意を狭める場合がある。'])
add(10,381,[(1,[1]),(2,[1]),(3,[1]),(4,[1])],'反復と熟練は今回の未知条件や理解確認を省けない','熟練の配管作業者が初めての接続方式を担当し、説明にはうなずいている。適切な対応はどれか。',['未知の範囲を具体化し、今回の条件を経験と照合し、作業者の言葉でも理解を確かめる。','経験年数が長ければ、新しい方式の知識も十分といえる。','質問がないことが、全条件を理解した証拠になる。','前の箱に似ていれば、途中の品番変更も確認不要である。'],'経験と今回の知識は別で、うなずきや無質問は理解の証明ではない。反復による確認漏れも考える。',['特定の新方式を知らない可能性がある。','沈黙を理解した証拠とは読まない。','反復作業でも変更や状態の違いがあり得る。'])
add(10,382,[(1,[1]),(2,[1]),(3,[1]),(4,[1])],'工期遅れと集団同意は点検省略の根拠にならない','搬入が遅れ、班全員が点検を省こうと賛成した。管理側の適切な考え方はどれか。',['必要な確認を含めて工程・人員や作業の重なりを見直し、経験や同意を省略の根拠にしない。','全員の賛成があれば、安全条件は成立する。','長く故障なく使った工具は、今日の点検を省略できる。','作業者の我慢を増やせば、工程と安全の条件はすべて解決する。'],'慣れ、遅れ、集団の雰囲気を条件の代わりにせず、管理上の工程や負荷にも安全を組み込む。',['多数決や全員同意は安全の証拠ではない。','過去の状態と現在の点検結果は別である。','安全を個人の耐久だけに頼る計画にはしない。'])
add(10,383,[(1,[1]),(2,[1]),(3,[1]),(4,[1])],'曖昧な指示の対象理解と変更到達範囲を照合する','「その管を変更」という日付なしのメモがある。責任者には電話したが、昼に作業者が交代した。適切なのはどれか。',['管の識別と適用時点、交代者への伝達・理解を具体的に照合する。','同じ色の管なら、作業者の予想した方を対象としてよい。','はいという返事があれば、対象と範囲の理解は一致している。','朝の電話一件で全員に届いたとし、日付のない内容を今日の確定事項とする。'],'聞こえたこと、意味の理解、現場作業者への伝達、指示の適用時点はそれぞれ確認対象である。',['曖昧な対象を予想だけで補っている。','返事や音の反復だけは理解の証拠ではない。','交代者への到達とメモの時点が未確認である。'])
add(10,384,[(1,[1]),(2,[1]),(3,[1]),(4,[1])],'反射行動とパニックを予測し区域変更時の緊急計画も更新する','狭い作業場所の下に通路があり、その通路を変更する。備えとして適切なのはどれか。',['驚いた動きや工具を放す可能性も考え、区域・工具管理と緊急時の連絡・退避情報を更新する。','落ち着いた立ち姿の写真で、驚いたときも含め全動作を見積もれる。','工具を放す例は、驚いたときに放す操作を推奨するものである。','通常の通路案内だけ変えれば、以前の緊急時情報は永久に使える。'],'反射的動作や慌てによる判断の乱れを考え、物と人の配置と役割を事前に準備する。区域変更は緊急条件にも関わる。',['人が常に予定どおり動くとは限らない。','危険の例を推奨手順と読み違えている。','通路変更で退避や連絡の条件も変わり得る。'])
add(10,385,[(1,[1]),(2,[1]),(3,[1]),(4,[1])],'心身個人差と疲労は環境・仕事負荷も調整する','同年齢の二人のうち、一人が暗い棚で品番を読み違え、残業後に普段と違う疲れを訴えた。適切な考えはどれか。',['個別状態と照明・表示、工程・休憩の条件を見直し、適切な窓口へ異変をつなげる。','年齢が同じなので能力と視力も同じと判断する。','注意を増やすよう求めれば、照明や表示の確認は不要である。','睡眠だけを求めれば、仕事の負荷や休憩を確認する必要はない。'],'年齢だけで能力を決めず、環境と生活・仕事量を合わせて考える。異変は我慢や憶測で済ませず必要な対応へつなぐ。',['心身・視力には個人差がある。','見間違いは環境側の条件にも関わる。','疲労には生活と仕事量の両方が関わる。'])
add(10,360,[(1,[1,2]),(4,[1,2])],'炉の墨出し基準識別と水平垂直の測定を写真で代用しない','炉には旧補修線と新しい線があり、完成写真は斜めから撮られている。位置と向きを判断する方法はどれか。',['指定基準線を識別し、水平・垂直は基準に対する測定結果として扱う。','最も見えやすい線を新しい基準として採用する。','写真の画面に対してまっすぐなら、炉は鉛直である。','写真の撮影角度を、そのまま炉の傾きの測定値にする。'],'線の視認性と正しい基準は異なる。水平・垂直は基準への向きであり、斜め写真の見え方は測定結果を代用しない。',['濃さや見えやすさは指定基準の識別ではない。','画面上の見え方は基準に対する鉛直の測定ではない。','撮影方向と炉の傾きは別である。'])
add(10,373,[(2,[1,2])],'巡視指摘と指示後の是正確認は異なる段階である','巡視で柵不足を記録し、補うよう指示した。改善の完了を示すために必要なのはどれか。',['指示後に、対象の状態が改善されたことを確認する。','巡視の回数が前日より多かったことを示す。','指摘を書いた欄に署名があることだけを示す。','柵不足という言葉を相手へ伝えた事実だけを示す。'],'巡視は必要な対応へつなぐ活動である。指摘や指示と実際の改善は異なるため、指示後の状態を確かめる。',['回数は改善の結果ではない。','記入や署名だけでは現物の改善は分からない。','伝達の事実と改善された状態を混同している。'])
blueprint=json.loads((root/'blueprint.json').read_text())
for e,questions in exams.items():
 slots=next(x for x in blueprint['exams'] if x['examNumber']==e)['slots'];assert len(questions)==len(slots)==40
 sources={a['session']['id']:a['session'] for a in json.loads((root/f'source-exam-{e:02}.json').read_text())}
 for q,slot in zip(questions,slots):
  assert q['number']==slot['number']
  assert len(q['choicesJa'])==len(q['distractorRationalesJa'])==4 and len(set(q['choicesJa']))==4 and q['correctIndex']==0
  assert len(q['objectiveKey'])>8 and q['explanationJa']
  assert int(q['sourceReferences'][0]['sessionId'].split('-')[-1])==slot['session']
  for ref in q['sourceReferences']:
   s=sources[ref['sessionId']];c=next(c for c in s['clusters'] if c['id']==ref['clusterId']);ids={p['id'] for p in c['paragraphs']}
   assert set(ref['paragraphIds'])<=ids and ref['paragraphIds']
 assert len({q['objectiveKey'] for q in questions})==40
 out={'examNumber':e,'titleJa':f'建設学習確認 第{e}回','questions':questions}
 (root/f'author-exam-{e:02}.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n')
 print(json.dumps({'exam':e,'questions':len(questions),'paragraphReferences':sum(len(r['paragraphIds']) for q in questions for r in q['sourceReferences']),'uniqueObjectives':len({q['objectiveKey'] for q in questions})}))
